select case when amount >= 4000 then 'HIGH' else 'LOW' end as amount_tier, date_trunc('quarter', txn_time) as quarter_start, txn_type, round(sum(amount) / nullif(count(case when merchant = 'Amazon' then 1 end), 0), 2) as amount_per_amazon, size(collect_set(merchant)) as num_merchants from transactions group by case when amount >= 4000 then 'HIGH' else 'LOW' end, date_trunc('quarter', txn_time), txn_type order by amount_per_amazon desc;
